package com.bank.synthetic;

import java.util.*;
import java.util.logging.*;

public class GenerateDemo {
    private static final Logger log = Logger.getLogger("Synthetic");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        SyntheticDataService service = new SyntheticDataService();
        List<Long> salaries = service.randomSalaries(10);
        log.info(() -> "10 synthetic salaries: " + salaries);
    }
}

// ─── Would be in service/SyntheticDataService.java ───
class SyntheticDataService {
    List<Long> randomSalaries(int count) {
        return java.util.stream.Stream.generate(Math::random)   // INFINITE stream
            .map(r -> Math.round(r * 1_000_000))                 // scale to salary range
            .limit(count)                                        // BOUND it (must!)
            .toList();
    }
}
